from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LowVolatilityTilting(Strategy):
    rationale = (
        "Low-volatility stocks tend to outperform high-volatility stocks over the long term. "
        "This is because low-volatility stocks often exhibit lower downside risk and can offer "
        "more stable returns. By tilting towards these stocks, we aim to capture this premium."
    )

    def __init__(self, window: int = 250) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        low_vol_symbols = []
        for symbol in view.symbols:
            if symbol not in history.columns:
                continue
            daily_returns = (
                (history[symbol].close / history[symbol].adj_close.shift(1) - 1.0).drop_nulls()
            ).to_list()
            if len(daily_returns) < self._window:
                continue
            vol = pl.DataFrame({"returns": daily_returns}).select(
                (pl.col("returns").std()).alias("volatility")
            )
            if not vol.is_empty():
                low_vol_symbols.append((symbol, float(vol[0]["volatility"])))

        # Sort by volatility and select top N symbols with lowest volatility
        low_vol_symbols.sort(key=lambda x: x[1])
        low_vol_symbols = [x[0] for x in low_vol_symbols[:5]]

        if not low_vol_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(low_vol_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in low_vol_symbols}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
